      host.innerHTML=`<div class="build-modal"><span class="eyebrow">${esc(build.gameName)}</span><h2>Choose where your agent builds</h2><p>Send your plan to a shared Studio worker or connect your own Studio The coin page shows real worker updates and captured frames when available</p>
      <section class="build-setup-step"><span class="build-step-num">01</span><div><h3>${build.plan?'Build plan prepared':'Choose a build plan'}</h3>${build.plan?`<p>${esc(build.planSource==='model'?'AI game plan':'Historical plan')} · ${build.plan.parts.length} scene objects · ${esc(build.status.replaceAll('_',' '))}</p>`:`<p>Your advanced model designs an original game plan from your prompt and references Review the plan before sending it to Studio</p><label>AI planning model<select id="build-ai-model" disabled><option value="">Loading available models</option></select></label><div class="build-setup-actions"><button class="button primary" id="build-generate" disabled>Design with AI ↗</button></div><p class="build-modal-note" id="build-ai-note">Paid generation uses the server’s daily compute budget</p>`}</div></section>
      <section class="build-setup-step build-queue-option"><span class="build-step-num">02</span><div><span class="eyebrow">OPTION A / SHARED WORKERS</span><h3>Queue a Studio build</h3><p>${pool ? `${online} workers online · ${Number(pool.active)||0} building · ${Number(pool.queued)||0} queued · ${pool.capacity} worker slots` : 'Worker availability is currently unavailable'}</p>${queue==='queued'?`<p class="build-queue-state">Your project is queued${Number.isInteger(build.queue.position)?' at position #'+build.queue.position:''}</p>`:queue==='claimed'?`<p class="build-queue-state">Assigned to ${esc(build.queue.workerId||'a Studio worker')}</p>`:queue==='completed'?'<p class="build-queue-state">Worker reported assembly complete Playtesting is still required</p>':''}<p>${queue==='failed'||build.status==='failed'?'This execution is closed Review its recorded error and create a game update for another attempt':online===0?'No worker is online Queued projects wait until an operator connects Studio':queue==='claimed'?'Your assigned worker reports build progress to the workspace':'A worker takes one project at a time and applies the prepared plan in Studio'}</p><div class="build-setup-actions">${canQueue?'<button class="button primary" id="build-enqueue">Queue Studio build ↗</button>':!build.plan?'<span class="build-modal-note">Prepare a plan above to join the queue</span>':''}${queue==='queued'?'<button class="button" id="build-cancel-queue">Cancel queued build</button>':''}${queue==='failed'||build.status==='failed'?'<button class="button" id="build-new-attempt">Create a game update ↗</button>':''}</div><p class="build-modal-note">Queueing does not generate another AI plan or publish the game Download the generated project from its workspace and playtest before publishing from your account</p></div></section>
      <section class="build-setup-step"><span class="build-step-num">03</span><div><span class="eyebrow">OPTION B / YOUR STUDIO</span><h3>Pair your own Roblox Studio</h3><p>Open a new blank place Install the bridge as a local Studio plugin, then paste the workspace ID and connection token into its panel Approve Studio’s localhost HTTP access when prompted</p><div class="build-setup-actions"><a class="button" href="/api/builds/bridge" download>Download Studio bridge ↓</a><button class="button" id="build-pair"${queueActive||agentActive(build)?' disabled':''}>Create connection token</button></div>${queueActive?'<p class="build-modal-note">This project uses the shared pool connection Waiting jobs can be cancelled Completed or failed jobs remain closed</p>':''}<details class="build-install-help"><summary>How to install the bridge</summary><ol><li>In Studio, create a Script and paste the downloaded bridge code</li><li>Right-click the Script and choose Save as Local Plugin</li><li>Remove that temporary Script from the place</li><li>Open Plugins → Ropad → Build connection and paste the fields below</li></ol><p>Builds go into a new workspace folder Existing game content is preserved Publishing and playtesting stay in Studio</p></details><div id="build-pairing"></div></div></section>
      <section class="build-setup-step"><span class="build-step-num">04</span><div><h3>Share your Studio screen</h3><p>Select only the Roblox Studio window in your browser’s screen picker Captured frames will be visible on this workspace page until you stop sharing</p><div class="build-setup-actions"><button class="button" id="build-share">${activeShare?.id===id?'Screen sharing active':'Share Studio window ↗'}</button><button class="button" id="build-stop"${activeShare?.id===id?'':' hidden'}>Stop sharing</button></div><p class="build-modal-note">A screen share shows what is on the selected window It does not grant remote mouse or keyboard access</p><video id="build-share-preview" muted playsinline hidden></video></div></section><p data-build-feedback role="status"></p></div>`;
      host.querySelector('.build-queue-option>div')?.insertAdjacentHTML('beforeend',`<p class="build-modal-note" role="status">${esc(queueGate.reason)}</p>${!queueGate.ready&&build.plan&&!['queued','claimed','completed','failed'].includes(queue)&&!['building','ready','failed'].includes(build.status)?'<button class="button" disabled>Worker validation required</button>':''}`);
      const enqueue=host.querySelector('#build-enqueue'),cancel=host.querySelector('#build-cancel-queue');
      if(enqueue)enqueue.onclick=()=>window.queueRobloxBuild(id,enqueue);
      if(cancel)cancel.onclick=()=>window.cancelRobloxQueue(id,cancel);
      const nextAttempt=host.querySelector('#build-new-attempt');if(nextAttempt)nextAttempt.onclick=()=>window.updateRobloxGame(id);
      host.querySelector('#build-pair').onclick=async()=>{try{const p=await api('/api/builds/'+id+'/connect',{});if(epoch!==connectionEpoch)return;const slot=host.querySelector('#build-pairing');slot.innerHTML=`<div class="build-pairing"><label>Server<input readonly value="${esc(p.baseUrl)}"></label><label>Workspace ID<input readonly value="${esc(p.sessionId)}"></label><label>Connection token<input type="password" readonly id="build-worker-token"></label><button class="text-button" id="build-copy-token">Copy connection token ↗</button><small>Valid for 12 hours Creating a new token revokes the previous token</small></div>`;slot.querySelector('#build-worker-token').value=p.workerToken;slot.querySelector('#build-copy-token').onclick=async()=>{try{await navigator.clipboard.writeText(p.workerToken);feedback('Connection token copied — paste it only into your Studio bridge');}catch{feedback('Select and copy the connection token field',true);}};}catch(e){feedback(e.message,true);}};
      host.querySelector('#build-share').onclick=()=>startShare(id,epoch);
